class Solution {
public:
    int minCostToSupplyWater(int n, vector<int>& wells, vector<vector<int>>& pipes) {
        vector<tuple<int, int, int>> edges;
        for (int i = 0; i < n; ++i) {
            edges.push_back({wells[i], 0, i + 1});
        }
        for (const auto& p : pipes) {
            edges.push_back({p[2], p[0], p[1]});
        }
        sort(edges.begin(), edges.end());

        vector<int> parent(n + 1);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto& self, int x) -> int {
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };

        int total_cost = 0, count = 0;
        for (const auto& [cost, u, v] : edges) {
            int pu = find(find, u), pv = find(find, v);
            if (pu != pv) {
                parent[pu] = pv;
                total_cost += cost;
                count++;
                if (count == n) break;
            }
        }
        return total_cost;
    }
};

import java.util.*;

class Solution {
    int[] parent;

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public int minCostToSupplyWater(int n, int[] wells, int[][] pipes) {
        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new int[]{wells[i], 0, i + 1});
        }
        for (int[] p : pipes) {
            edges.add(new int[]{p[2], p[0], p[1]});
        }
        edges.sort((a, b) -> Integer.compare(a[0], b[0]));

        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;

        int totalCost = 0, count = 0;
        for (int[] e : edges) {
            int pu = find(e[1]), pv = find(e[2]);
            if (pu != pv) {
                parent[pu] = pv;
                totalCost += e[0];
                count++;
                if (count == n) break;
            }
        }
        return totalCost;
    }
}

var minCostToSupplyWater = function(n, wells, pipes) {
    const edges = [];
    for (let i = 0; i < n; i++) {
        edges.push([wells[i], 0, i + 1]);
    }
    for (const [u, v, cost] of pipes) {
        edges.push([cost, u, v]);
    }
    edges.sort((a, b) => a[0] - b[0]);

    const parent = Array.from({ length: n + 1 }, (_, i) => i);
    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    let totalCost = 0, count = 0;
    for (const [cost, u, v] of edges) {
        const pu = find(u), pv = find(v);
        if (pu !== pv) {
            parent[pu] = pv;
            totalCost += cost;
            count++;
            if (count === n) break;
        }
    }
    return totalCost;
};
